import type { DroneColorId } from '../types'

interface PartImageProps {
  /** Part-image key (matches the `img` field on a step), e.g. "main_frame". */
  img: string
  /** Which colour-way folder to pull from. */
  color: DroneColorId
  alt: string
  className?: string
}

/**
 * Renders a part render from `public/drone-parts/<color>/<img>.png`.
 * Replaces the old inline-SVG `PartFigure` now that every part is a real image
 * in three colour-ways (blue / orange / grey, generated by
 * `scripts/gen-part-colors.mjs`).
 */
export function PartImage({ img, color, alt, className }: PartImageProps) {
  return (
    <img
      src={`/drone-parts/${color}/${img}.png`}
      alt={alt}
      className={`part-image${className ? ` ${className}` : ''}`}
      loading="lazy"
      draggable={false}
    />
  )
}
